            { "Security Tactical Officer", "Agent tactique de la Sécurité" },
            { "Security needs equipment: {0} {1} ({2}, legal guns only), {3} at least {4}. Two batches: {6} in {5} days, {8} in {7} days. {9} credits a gun, paid on delivery. Miss a date and the contract is off.", "La Sécurité doit renouveler son équipement : {1}, quantité {0} ({2}, armes légales uniquement), {3} d'au moins {4}. En deux lots : {6} dans {5} jours, {8} dans {7} jours. {9} crédits par arme, payés à la livraison. Au moindre retard, le contrat est annulé." },
            { "Security procurement officer", "Agent d'approvisionnement de la Sécurité" },
            { "See you tonight.", "À ce soir." },
            { "See you, bro! Call me on the line anytime!", "À plus, frérot ! Au moindre besoin, appelle-moi sur la ligne directe !" },
            { "See you, bro! Watch out for the patrols, and call me on the line anytime!", "À plus, frérot ! Gare aux patrouilles en route, et au moindre besoin, appelle-moi sur la ligne directe !" },
            { "See you, partner.", "À bientôt, associé." },
            { "See you.", "À une prochaine fois." },
            { "See you. There's new stock waiting at the shop.", "À bientôt. De nouveaux arrivages vous attendent à la boutique." },
            { "Serial number filed off (stolen)", "Numéro de série limé (arme volée)" },
            { "Settled. Go and show this station what a good gun is.", "Compte soldé. Allez montrer à la station ce qu'est une bonne arme." },
            { "Shadowbox Bullpup Sniper Rifle", "Fusil de sniper bullpup Boîte-d'ombre" },
            { "Shame. The guild won't trouble you again.", "Dommage. La guilde ne vous dérangera plus." },
            { "Sharp eye. Not many of these old pieces get out.", "Vous avez l'œil. Peu de vieilles pièces comme celle-ci circulent." },
            { "Shelf ({0}-{1} / {2} rows)", "Rayon ({0}-{1} / {2} rangées)" },
            { "Shh, keep it down, bro! This rare one took a lot to get here!", "Chut, moins fort, frérot ! Celle-là, ça a été galère de la faire venir, c'est une rareté !" },
            { "Short Handguard", "Garde-main court" },
